  (forall q, ~ (sblk sel1 sv1 q \/ sblk sel2 sv2 q \/ tblk pixsb datab cdb cvb q) -> live A0 q = live A q) ->
  aroom A0 vm0 kx bx ->
  (kR - RK_csc (vsz sh) + (3 * RK_pixcopy + RK_cmapcopy) <= kx)%Z ->
  (bR - RB_csc (vsz sh) w h cm + (2 * (RB_pixT (4 * (wpl_of (w + 64) 1 * (h + 64))) + RB_cmapT cm) + (RB_pixT (4 * (wpl_of w 1 * h)) + RB_cmapT cm) + RB_cmapT cm) <= bx)%Z ->
  (0 <= kR - RK_csc (vsz sh))%Z -> (0 <= bR - RB_csc (vsz sh) w h cm)%Z ->
  csc_K fr C Ar A m md regs s pix1 (vsz sh) w h cm datas cv ret S kR bR ->
  realizes SEGS (mkCfg (@mkst (mkFP fr1 cs1) r0 (0x9224c : word) m0 al_rom) (with_vmmaps vm0 md)) S.
